let cart = [];

function showProducts(list = products) {
  const box = document.getElementById("products");
  box.innerHTML = "";

  list.forEach((p) => {
    const realIndex = products.indexOf(p);
    const isOut = p.stock === "OUT OF STOCK";

    box.innerHTML += `
      <div class="card ${isOut ? 'out-card' : ''}">
        <img src="${p.image}" alt="${p.name}">
        <h3>${p.name}</h3>
        <p class="price">₹${p.price}</p>

        ${isOut
          ? `<p class="out-stock">${p.stock}</p>`
          : `
            <button class="add" onclick="addToCart(${realIndex})">Add to Cart</button>
            <button class="buy" onclick="buyNow(${realIndex})">Buy on WhatsApp</button>
          `
        }
      </div>
    `;
  });
}

function filterProducts(category) {
  if (category === "all") {
    showProducts(products);
  } else {
    showProducts(products.filter(p => p.category === category));
  }
}

function searchProducts() {
  const text = document.getElementById("search").value.toLowerCase();
  const result = products.filter(p => p.name.toLowerCase().includes(text));
  showProducts(result);
}

function addToCart(index) {
  if (products[index].stock === "OUT OF STOCK") {
    alert("Ye product OUT OF STOCK hai");
    return;
  }

  cart.push(products[index]);
  document.getElementById("cartCount").innerText = cart.length;
  alert("Product added!");
}

function openCart() {
  document.getElementById("cartBox").style.display = "block";
  const cartItems = document.getElementById("cartItems");
  cartItems.innerHTML = "";

  let total = 0;

  cart.forEach(item => {
    total += item.price;
    cartItems.innerHTML += `
      <div class="cart-item">
        <b>${item.name}</b><br>
        ₹${item.price}
      </div>
    `;
  });

  cartItems.innerHTML += `<h3>Total: ₹${total}</h3>`;
}

function closeCart() {
  document.getElementById("cartBox").style.display = "none";
}

function buyNow(index) {
  if (products[index].stock === "OUT OF STOCK") {
    alert("Ye product OUT OF STOCK hai");
    return;
  }

  const p = products[index];
  const msg = `Hello bhai, mujhe ye product chahiye:%0AProduct: ${p.name}%0APrice: ₹${p.price}`;
  window.open(`https://wa.me/${+916280083845}?text=${msg}`, "_blank");
}

function sendCartWhatsApp() {
  if (cart.length === 0) {
    alert("Cart empty hai");
    return;
  }

  let msg = "Hello bhai, mujhe ye order chahiye:%0A%0A";
  let total = 0;

  cart.forEach((item, i) => {
    msg += `${i + 1}. ${item.name} - ₹${item.price}%0A`;
    total += item.price;
  });

  msg += `%0ATotal: ₹${total}`;
  window.open(`https://wa.me/${+916280083845}?text=${msg}`, "_blank");
}

